step3_testbench.spice:
* UWB LNA Input Matching Network Testbench
.lib "${SKY130_PDK}" tt

.param R_s=50 R_w=5 C_gd=20f C_2=300f C_1=500f C_p=100f L_2=2n L_1=1n L_g=1.5n L_s=0.5n

* DUT
Rs Vin N2 {R_s}
V1 N2 GND DC 0 AC 2
RwTLs N0 GND {R_w}
Cgd N4 GND {C_gd}
C2 Vbias N5 {C_2}
C1 N5 N6 {C_1}
Cp_Cgs N0 N7 {C_p}
L2 Vbias N5 {L_2}
L1 Vin N6 {L_1}
Lg N4 N5 {L_g}
Ls N4 N7 {L_s}

* Bias
VVBIAS Vbias GND 0.75

.control
ac dec 100 1G 15G

* Calculate S11
* V(Vin) with V1=2V and Rs=50 is V_in = 2 * Zin / (Zin + 50)
* S11 = (Zin - 50) / (Zin + 50) = V_in - 1
let v_in_r = real(v(Vin))
let v_in_i = imag(v(Vin))
let s11_mag = sqrt((v_in_r - 1)*(v_in_r - 1) + v_in_i*v_in_i)
let s11_db = 20 * log10(s11_mag)

* Calculate Passive Voltage Gain (Voltage across Cgs relative to V1)
let v_cgs_r = real(v(N7) - v(N0))
let v_cgs_i = imag(v(N7) - v(N0))
let v_cgs_mag = sqrt(v_cgs_r*v_cgs_r + v_cgs_i*v_cgs_i)
let gain_db = 20 * log10(v_cgs_mag / 2)

* Measurements
meas ac max_gain max gain_db
meas ac min_s11 min s11_db
meas ac s11_center find s11_db at=6.85G
meas ac gain_center find gain_db at=6.85G

print max_gain min_s11 s11_center gain_center
quit
.endc
.end

